// CONFIG — the only place that knows about accounts.
// Add account #3 = add one row here + a NOTION_TOKEN_<workspace> n8n Variable.
return [
  { json: { workspace: 'marketing_vt', dataSourceId: '20e248f7-4b65-44eb-bfd4-90dac48a79d7' } },
  { json: { workspace: 'gifted',       dataSourceId: 'REPLACE_WITH_GIFTED_MEDIA_LIBRARY_DATASOURCE_ID' } }
];

// Explode Notion query results into one item per page, carrying account context.
const out = [];
for (const acct of $input.all()) {
  const workspace = acct.json.workspace;
  const dbId = acct.json.dataSourceId;
  const results = (acct.json.results) || [];
  for (const page of results) {
    const p = page.properties || {};
    const txt = (x) => (x && x.rich_text && x.rich_text[0] && x.rich_text[0].plain_text) || '';
    const sel = (x) => (x && x.select && x.select.name) || '';
    const chk = (x) => !!(x && x.checkbox);
    const dt  = (x) => (x && x.date && x.date.start) || null;
    const fileUrl = (() => { const f = p['Image'] && p['Image'].files && p['Image'].files[0]; if(!f) return ''; return (f.file && f.file.url) || (f.external && f.external.url) || ''; })();
    out.push({ json: {
      workspace, notion_database_id: dbId, notion_page_id: page.id,
      media_type: sel(p['Media Type']) || 'other',
      alt_th: txt(p['Alt (TH)']), alt_en: txt(p['Alt (EN)']),
      caption_th: txt(p['Caption TH']), caption_en: txt(p['Caption EN']),
      is_patient_image: chk(p['Patient image?']),
      consent_status: sel(p['Consent status']) || null,
      consent_doc_url: (p['Consent doc'] && p['Consent doc'].url) || null,
      consent_obtained_at: dt(p['Consent date']),
      usage_perpetual: chk(p['Use forever?']),
      usage_expires_at: dt(p['Use until']),
      patient_ref: txt(p['Patient ref']) || null,
      image_url: fileUrl
    }});
  }
}
return out;

// Compute the R2 key — MUST namespace by workspace/brand to stay globally unique (gotcha #1).
const slugify = (s) => (s||'asset').toString().toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);
for (const it of $input.all()) {
  const j = it.json;
  const base = slugify(j.alt_en || j.alt_th || j.notion_page_id);
  j.r2_key = `${j.workspace}/${j.media_type}/${base}.webp`;
  j.cdn_url = `https://cdn.smilescapeclinic.com/${j.r2_key}`;
  it.json = j;
}
return $input.all();

